BAN_LIST_PATH = os.path.join(settings.BASE_DIR, 'subekashi', 'constants', 'dynamic', 'ban.py')

# 以下の定数と6つの関数は、#1281の時点のsubekashi/lib/security.pyのコピー
# lib/security.pyを後から変えても、このマイグレーションの挙動が変わったりimportできなくなったりしないよう、importせずにコピーしている
SYMBOLS = ".◘#∴¹▼᠂（◆ን"


def ip_to_int(ip):
    return int(ipaddress.ip_address(ip))


def pad(data, block_size=16):
    pad_len = block_size - (len(data) % block_size)
    return data + bytes([pad_len]) * pad_len


def encode_base_n(num):
    base = len(SYMBOLS)
    if num == 0:
        return SYMBOLS[0]
    result = ""
    while num > 0:
        num, rem = divmod(num, base)
        result = SYMBOLS[rem] + result
    return result


def sha256(check):
    check += settings.SECRET_KEY
    return hashlib.sha256(check.encode()).digest()


def encrypt(ip):
    ip_num = ip_to_int(ip)
    ip_bytes = ip_num.to_bytes((ip_num.bit_length() + 7) // 8 or 1, "big")
    cipher = AES.new(sha256(""), AES.MODE_ECB)
    encrypted = cipher.encrypt(pad(ip_bytes))
    num = int.from_bytes(encrypted, "big")
    return encode_base_n(num)


# 廃止するsubekashi/constants/dynamic/ban.pyのBAN_LISTにあるIPの編集者を、is_bannedにする（#1281）
# BAN_LISTはIPそのもので、Editor.ipは暗号化されているため、BAN_LISTのIPを暗号化して照合する
# 編集者が見つからないIPと、IPとして読めない値は、手作業で確認できるよう出力する
def ban_listed_editors(apps, schema_editor):
    Editor = apps.get_model('subekashi', 'Editor')
    # 編集者が1件もないDB（新規構築・テスト）には、照合する相手がいないため何もしない
    if not Editor.objects.exists():
        return

    if not os.path.exists(BAN_LIST_PATH):
        print(f"\n  {BAN_LIST_PATH} が無いため、BAN済みのIPの編集者をis_bannedにしませんでした。")
        return

    ban_list = runpy.run_path(BAN_LIST_PATH).get('BAN_LIST', [])
    ips = list(dict.fromkeys(str(ip).strip() for ip in ban_list if str(ip).strip()))
    if not ips:
        return

    ip_by_encrypted = {}
    invalid_ips = []
    for ip in ips:
        try:
            ip_by_encrypted[encrypt(ip)] = ip
        except ValueError:
            invalid_ips.append(ip)

    editors = list(Editor.objects.filter(ip__in=list(ip_by_encrypted)))
    Editor.objects.filter(pk__in=[editor.pk for editor in editors]).update(is_banned=True)

    found_encrypted = {editor.ip for editor in editors}
    not_found_ips = [ip for encrypted, ip in ip_by_encrypted.items() if encrypted not in found_encrypted]
    lines = [f"\n  BAN_LIST {len(ips)}件のうち{len(found_encrypted)}件の編集者をis_bannedにしました。"]
    lines += [f"  編集者を特定できないIP: {ip}" for ip in not_found_ips]
    lines += [f"  IPとして読めない値: {ip}" for ip in invalid_ips]
    print("\n".join(lines))


